const doc = $input.first().json;
let fullText = '';

if (doc.body && doc.body.content) {
  for (const element of doc.body.content) {
    if (element.paragraph && element.paragraph.elements) {
      for (const pe of element.paragraph.elements) {
        if (pe.textRun && pe.textRun.content) {
          fullText += pe.textRun.content;
        }
      }
    }
    if (element.table) {
      for (const row of element.table.tableRows || []) {
        for (const cell of row.tableCells || []) {
          for (const cellEl of cell.content || []) {
            if (cellEl.paragraph && cellEl.paragraph.elements) {
              for (const pe of cellEl.paragraph.elements) {
                if (pe.textRun && pe.textRun.content) {
                  fullText += pe.textRun.content + ' ';
                }
              }
            }
          }
        }
      }
    }
  }
}

if (!fullText.trim()) {
  fullText = doc.content || JSON.stringify(doc);
}

return [{
  json: {
    text: fullText,
    title: doc.title || 'document',
    source: 'google_docs'
  }
}];
